globalThis.SuperconExternalResearch = {"entries":[{"boundary":"这些是计算候选，尚非实验超导样品。筛选未计入非谐效应，结构数、候选数和实验成功数不可互换。","category":"计算预测","doi":"10.1093/nsr/nwag030","evidence_type":"理论计算","extra":[["公开全文","https://pmc.ncbi.nlm.nih.gov/articles/PMC13023052/"]],"heading":"三元氢化物的大规模结构搜索","headline":"144个候选 Tc≥200 K；200 GPa","id":"01","pressure":"200 GPa","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1093/nsr/nwag030"},{"label":"公开全文","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13023052/"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"National Science Review 13, nwag030 (2026)","reference_point":"用势模型扩大结构搜索范围，再用更昂贵的物理计算逐级筛选；保留每一层筛选的物理近似。","result":"深度学习原子势与CALYPSO结构搜索结合，探索约3600万个三元氢化物结构，再经稳定性和超导性质计算筛选。在200 GPa下提出144个预测Tc≥200 K的候选，作者称其中129个此前未报道。","reviewed_on":"2026-11-01","short":"Wang等 三元氢化物","stage":"理论预测","tc_criterion":"计算Tc；非实测","team":"Xiaoyang Wang等，中国多机构团队","title":"Computational discovery of high-temperature superconducting ternary hydrides via deep learning","url":"https://doi.org/10.1093/nsr/nwag030","verified_version":"正式论文","year":"2026"},{"boundary":"该论文未报告这些候选的超导实验验证。2026年Mg₂RhH₆实验后续见条目13；其压力和温度与原先常压预测不同。","category":"计算预测","doi":"10.1038/s41524-024-01214-9","evidence_type":"理论计算","heading":"常压氢化物家族的机器学习筛选","headline":"常压预测45–80 K；掺杂Pt体系\u003e100 K","id":"02","pressure":"常压计算","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-024-01214-9"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"npj Computational Materials 10, 44 (2024)","reference_point":"把候选限定在明确结构家族内，比较电子填充与耦合强度；跟踪预测家族的后续实验。","result":"机器学习加速筛查超过100万种化合物，结合物理计算提出Mg₂XH₆家族，X为Rh、Ir、Pd或Pt。常压预测Tc约45–80 K，适当电子掺杂的Pt体系可能超过100 K。","reviewed_on":"2026-11-01","short":"Sanna等 Mg₂XH₆","stage":"理论预测","tc_criterion":"计算Tc；含掺杂情景","team":"Antonio Sanna等，跨机构计算材料团队","title":"Prediction of ambient pressure conventional superconductivity above 80 K in hydride compounds","url":"https://www.nature.com/articles/s41524-024-01214-9","verified_version":"2024正式论文；2026实验另列13","year":"2024"},{"boundary":"提出合成路线不等于完成合成。后续考虑量子和热涨落的研究得到不同结构状态及约22 K估计，见条目14；两者均为理论结果。","category":"计算预测","doi":"10.1103/PhysRevB.111.L140501","evidence_type":"理论计算","heading":"InvDesFlow提出Li₂AuH₆候选","headline":"Li₂AuH₆常压预测约140 K","id":"03","pressure":"常压计算","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1103/PhysRevB.111.L140501"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Physical Review B 111, L140501 (2025)","reference_point":"候选生成之后仍需核实亚稳态寿命、有限温度结构和非谐效应，不能只检查谐近似声子。","result":"结合AI逆向设计工具InvDesFlow与第一性原理计算，提出以AuH₆八面体为特征的Li₂AuH₆候选，预测常压Tc约140 K，并讨论可能的合成路线。","reviewed_on":"2026-11-01","short":"Ouyang等 InvDesFlow","stage":"理论预测","tc_criterion":"计算Tc","team":"Ouyang等，中国人民大学团队","title":"High-temperature superconductivity in Li₂AuH₆ mediated by strong electron-phonon coupling under ambient pressure","url":"https://doi.org/10.1103/PhysRevB.111.L140501","verified_version":"2025正式论文；后续理论另列14","year":"2025"},{"boundary":"数值指该Ga系列的Tc,max，不是所有含Ga候选的上限，也不是实测温度。留一验证仍在铜氧化物小样本内；全数据先选公式的流程不能据此视为跨家族盲测。","category":"计算预测","doi":"10.1021/acs.jpclett.1c01442","evidence_type":"模型与物理关系预测","extra":[["作者稿及方法细节","https://arxiv.org/abs/2101.02810"]],"heading":"机制相关特征指导含镓铜氧化物设计","headline":"Ga系列一至三层预测71／117／131 K","id":"04","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1021/acs.jpclett.1c01442"},{"label":"作者稿及方法细节","url":"https://arxiv.org/abs/2101.02810"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"The Journal of Physical Chemistry Letters 12, 6211–6217 (2021)","reference_point":"把结构和电子态特征用于可解释的候选设计，同时区分家族内预测与新家族泛化。","result":"以29种已知空穴掺杂铜氧化物为基础，使用顶位氧电荷、顶位原子间力、CuO₂层数和顶位氧高度等特征构建回归模型。GaBa₂Caₙ₋₁CuₙO₂ₙ₊₂系列中，n=1、2、3的预测最优掺杂Tc分别为71、117、131 K。","reviewed_on":"2026-11-01","short":"Lee等 含Ga铜氧化物","stage":"理论预测","tc_criterion":"Ga系列预测Tc,max","team":"D. Lee、D. You、D. Lee、X. Li、S. Kim","title":"Machine-Learning-Guided Prediction Models of Critical Temperature of Cuprates","url":"https://doi.org/10.1021/acs.jpclett.1c01442","verified_version":"正式论文；家族内小样本","year":"2021"},{"boundary":"论文未报告该配方的合成与超导测量，也没有由此确定唯一晶体结构。元素属性汇总不是同一样品的正常态实测曲线，SHAP相关性也不构成机制因果证明。","category":"计算预测","doi":"10.1039/D3RA02848H","evidence_type":"成分模型预测","extra":[["公开全文","https://pmc.ncbi.nlm.nih.gov/articles/PMC10315706/"]],"heading":"铜氧化物虚拟配方的深度学习筛选","headline":"虚拟配方预测152 K","id":"05","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1039/D3RA02848H"},{"label":"公开全文","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10315706/"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"RSC Advances 13, 19836–19845 (2023)","reference_point":"双描述符可用于比较信息来源，但配方预测还须经过结构、可合成性及样品条件核验。","result":"用组成描述符和元素物性描述符训练并组合深度神经网络，在Hg–Pb–Ba–Ca–Cu–O空间进行虚拟筛选。原文给出的Hg₀.₁₃Pb₀.₀₉Ba₀.₃₂Ca₀.₄₂₂Cu₀.₄O₁配方预测Tc为152 K。","reviewed_on":"2026-11-01","short":"Wang等 Hg Pb铜氧化物","stage":"成分预测","tc_criterion":"预测Tc","team":"Yuxue Wang等，上海大学等","title":"Cuprate superconducting materials above liquid nitrogen temperature from machine learning","url":"https://doi.org/10.1039/D3RA02848H","verified_version":"正式论文；未报告该配方实验","year":"2023"},{"boundary":"没有生成完整晶体结构，所谓新家族主要由组成聚类判断，不能等同于新配对机制或实验发现。预测Tc曲线不是测得的超导相图。","category":"计算预测","doi":"10.1038/s41598-024-61040-3","evidence_type":"生成配方与模型评分","extra":[["作者代码仓库","https://github.com/sdkyuanpanda/SuperDiff"]],"heading":"SuperDiff生成假想配方家族","headline":"条件扩散生成配方；未实验确认新家族","id":"06","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41598-024-61040-3"},{"label":"作者代码仓库","url":"https://github.com/sdkyuanpanda/SuperDiff"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Scientific Reports 14, 10275 (2024)","reference_point":"参考材料可以引导局部化学空间探索；生成器和性质模型的输出仍需外部计算或实验检验。","result":"以96维化学组成向量训练扩散模型，并用参考配方约束采样，探索铜氧化物、铁基等假想配方族。形成能和Tc由其他模型估计；另在四版模型的无条件采样中，共265722个输出通过计算筛选。","reviewed_on":"2026-11-01","short":"Yuan和Dordevic SuperDiff","stage":"组成生成","tc_criterion":"模型预测；非测得相图","team":"Samuel Yuan、S. V. Dordevic","title":"Diffusion models for conditional generation of hypothetical new families of superconductors","url":"https://www.nature.com/articles/s41598-024-61040-3","verified_version":"已核作者稿；非完整晶体生成","year":"2024"},{"boundary":"这是事后回测，不是2008年前已经完成发现。1399条铁基记录上的平均约80条及中位44条非零预测不是实验命中数；未记录超导的COD材料被设为零，也不是真阴性。","category":"回溯验证","doi":"10.1103/PhysRevB.103.014509","evidence_type":"历史回测","heading":"从旧数据回测铁基超导体","headline":"用2008年前数据回测后来铁基材料","id":"07","pressure":"多来源；未统一","primary_refs":[{"label":"原始来源","url":"https://journals.aps.org/prb/abstract/10.1103/PhysRevB.103.014509"}],"progress_steps":[{"detail":"用2008年前记录训练","kind":"data","label":"历史数据","status":"completed"},{"detail":"检验后来铁基记录","kind":"validation","label":"事后回测","status":"completed"},{"detail":"该回测未完成前瞻发现","kind":"measurement","label":"前瞻实验","status":"not_reported"}],"publication":"Physical Review B 103, 014509 (2021)","reference_point":"采用时间截断与前驱材料排除检验迁移能力，并明确记录召回分母和未标记数据的处理。","result":"以类似元素周期表的方式编码成分，用深度模型开展时间截断回测。剔除LaFePO和LaFePFO等前驱例子后，作者报告仍能给部分后来出现的铁基材料非零Tc预测。","reviewed_on":"2026-11-01","short":"Konno等 铁基历史回测","stage":"历史回测","tc_criterion":"非零Tc预测；非实验命中","team":"Tomohiko Konno等","title":"Deep learning model for finding new superconductors","url":"https://journals.aps.org/prb/abstract/10.1103/PhysRevB.103.014509","verified_version":"2021正式论文及补充材料","year":"2021"},{"boundary":"优化目标是相纯度，不是发现新材料或提高Tc纪录。作者指出单变量问题中经验搜索也可能有效，未提供等预算的直接对照；重选旧温度时复用旧结果，不等于新增重复实验。","category":"实验研究","doi":"10.1016/j.jallcom.2023.171613","evidence_type":"实验工艺优化","heading":"贝叶斯优化铁基材料的制备条件","headline":"13次实验；最高相纯度91.3%","id":"08","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1016/j.jallcom.2023.171613"}],"progress_steps":[{"detail":"贝叶斯优化热处理温度","kind":"design","label":"工艺选择","status":"completed"},{"detail":"测相纯度，最高91.3%","kind":"measurement","label":"13次实验","status":"completed"},{"detail":"此项不以发现新材料为目标","kind":"discovery","label":"新材料发现","status":"not_reported"}],"publication":"Journal of Alloys and Compounds 966, 171613 (2023)","reference_point":"实验反馈可针对可测、可优化的工艺指标；成功与失败都应绑定制备条件，并保留试验预算。","result":"针对已知BaFe₂(As,P)₂材料，用高斯过程与期望改进选择热处理温度。作者称候选温度约800个；2次初始实验加11次迭代后，在863°C得到Rietveld分析相纯度91.3%。","reviewed_on":"2026-11-01","short":"Ishii等 铁基热处理优化","stage":"实验工艺优化","tc_criterion":"目标是相纯度；非Tc优化","team":"Akimitsu Ishii等","title":"Application of Bayesian optimization to the synthesis process of BaFe2(As,P)2 polycrystalline bulk superconducting materials","url":"https://doi.org/10.1016/j.jallcom.2023.171613","verified_version":"2023正式论文","year":"2023"},{"boundary":"均为低温结果。Be₂HfNb₂出现两个比热异常，存在多相问题；起始Tc不是中点Tc。模型报告的误差针对计算Tc，不能当作实验Tc预测误差。","category":"实验研究","doi":"10.1038/s41524-026-01964-8","evidence_type":"实验信号及物相限制","extra":[["作者稿v2","https://arxiv.org/html/2503.20005v2"]],"heading":"BEE NET从物理谱预测走向实验","headline":"Be₂Hf₂Nb／Be₂HfNb₂ 起始3.18／4.24 K","id":"09","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-026-01964-8"},{"label":"作者稿v2","url":"https://arxiv.org/html/2503.20005v2"}],"progress_steps":[{"detail":"BEE-NET加物理计算","kind":"design","label":"计算筛选","status":"completed"},{"detail":"电阻与热力学信号","kind":"measurement","label":"低温测量","status":"completed"},{"detail":"Be₂HfNb₂多相仍需保留","kind":"phase_validation","label":"物相归因","status":"current"}],"publication":"npj Computational Materials 12, 95 (2026)","reference_point":"学习物理中间量并用多个实验观测验证，同时把计算标签与实验标签分开。","result":"图神经网络学习电子—声子谱函数α²F(ω)，结合物理与稳定性计算，从约130万结构筛出741个计算候选，再开展合成。Be₂Hf₂Nb、Be₂HfNb₂电阻转变起始分别约3.18和4.24 K。","reviewed_on":"2026-11-01","short":"Gibson等 BEE NET","stage":"筛选加实验","tc_criterion":"电阻转变起始；非中点","team":"Gibson等，佛罗里达大学等","title":"Developing a complete AI-accelerated workflow for superconductor discovery","url":"https://www.nature.com/articles/s41524-026-01964-8","verified_version":"2026正式论文；多相边界保留","year":"2026"},{"boundary":"接近ZrNiIn₄的相高度亚稳，未分离成单相；约9 K不能直接替代电阻中点。不同筛选阶段的样品分母不同，不宜把成功比例变化全归因于模型。","category":"实验研究","doi":"10.1038/s41524-023-01131-3","evidence_type":"闭环实验；亚稳混相","extra":[["作者实验数据目录","https://data.paradim.org/doi/w3xm-w506/"]],"heading":"成分模型与实验组成闭环","headline":"Zr In Ni体系约9 K抗磁转变","id":"10","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-023-01131-3"},{"label":"作者实验数据目录","url":"https://data.paradim.org/doi/w3xm-w506/"}],"progress_steps":[{"detail":"推荐合成对象","kind":"design","label":"模型推荐","status":"completed"},{"detail":"多轮结果回到模型","kind":"feedback","label":"实验反馈","status":"completed"},{"detail":"约9 K相高度亚稳、未分离单相","kind":"phase_validation","label":"物相限制","status":"current"}],"publication":"npj Computational Materials 9, 181 (2023)","reference_point":"以真实实验结果更新候选选择，并将杂相、合成失败和样品不确定性一并保留。","result":"把成分预测、不确定度、新颖性、人工选择与合成测量组合，开展四轮实验迭代。除重发现已有超导体外，在Zr–In–Ni体系发现约9 K的超导抗磁转变信号及相关超导相线索。","reviewed_on":"2026-11-01","short":"Pogue等 Zr In Ni闭环","stage":"闭环实验","tc_criterion":"约9 K抗磁转变","team":"Pogue等","title":"Closed-loop superconducting materials discovery","url":"https://www.nature.com/articles/s41524-023-01131-3","verified_version":"2023正式论文；未分离单相","year":"2023"},{"boundary":"按指定作者稿版本记录，不能宣称已独立复现。电阻起始、零电阻和磁性Tc不同；论文也报告失败候选，并承认常规DFT对强关联材料的限制。","category":"实验研究","doi":"10.48550/arXiv.2604.23758","evidence_type":"预印本实验报告","heading":"ElementsClaw组织计算文献与实验任务","headline":"四种材料超导抗磁转变2.5–6.5 K","id":"11","pressure":"按各样品条件；未统一","primary_refs":[{"label":"原始来源","url":"https://arxiv.org/html/2604.23758v3"}],"progress_steps":[{"detail":"作者稿描述模型与工具协作","kind":"design","label":"AI工作流","status":"completed"},{"detail":"四种材料低温超导信号","kind":"measurement","label":"作者报告实验","status":"completed"},{"detail":"本核查未确认独立复现","kind":"replication","label":"独立复现","status":"not_reported"}],"publication":"arXiv:2604.23758 v3，2026年5月4日","reference_point":"语言模型承担文献与流程组织，数值性质由物理模型和实验检验；失败案例也能反映模型遗漏。","result":"把大原子模型与语言模型的文献理解和任务规划结合，在人工参与下筛查约240万晶体，报告四种新超导体：Zr₃ScRe₈、HfZrRe₄、Zr₄VRe₇、Hf₂₁Re₂₅；磁化测量中的超导抗磁转变对应Tc约2.5–6.5 K。","reviewed_on":"2026-11-01","short":"ElementsClaw","stage":"预印本实验报告","tc_criterion":"抗磁Tc；不混同电阻起始/零阻","team":"ElementsClaw研究团队","title":"Agentic Fusion of Large Atomic and Language Models to Accelerate Superconductor Discovery","url":"https://arxiv.org/html/2604.23758v3","verified_version":"指定作者稿；未声明独立复现","year":"2026"},{"boundary":"化合物本身早已存在，新结果是超导性质。Lu体系曾因计算中的弱虚频被初筛漏掉，后来作为同构材料研究；论文也承认Y体系有同期独立报告。","category":"实验研究","doi":"10.1103/lpqj-7hyg","evidence_type":"实验验证已有化合物的超导性质","heading":"在已知kagome化合物中确认超导","headline":"比热Tc 0.81／0.95 K","id":"12","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1103/lpqj-7hyg"}],"progress_steps":[{"detail":"计算与同构化合物比较","kind":"design","label":"筛选线索","status":"completed"},{"detail":"0.81/0.95 K超导性质","kind":"measurement","label":"比热确认","status":"completed"},{"detail":"已有化合物；保留漏筛与同期报告","kind":"boundary","label":"发现边界","status":"current"}],"publication":"Physical Review Research 8, 023308，2026年6月17日","reference_point":"稳定性筛选可能错失候选，边缘案例应允许更精细计算或实验复核。","result":"机器学习筛选、第一性原理计算与实验结合，在YRu₃B₂和LuRu₃B₂中确认体超导。零场比热等熵判据给出Tc=0.81和0.95 K，另有磁化及电输运支持；零电阻温度约0.84和1.04 K。","reviewed_on":"2026-11-01","short":"Rice Aalto等 Ru硼化物","stage":"筛选加实验","tc_criterion":"比热Tc 0.81/0.95 K","team":"Rose Albu Mustaf等，Rice、Aalto等","title":"Machine-learning-guided discovery of kagome superconductors YRu₃B₂ and LuRu₃B₂","url":"https://doi.org/10.1103/lpqj-7hyg","verified_version":"正式论文；已有化合物非新合成物","year":"2026"},{"boundary":"尚未实现条目02的常压预测。作者稿报告卸压后相发生变化、近常压恢复绝缘行为；实验本身没有被证实采用新的AI闭环。","category":"实验研究","doi":"10.1021/jacs.6c08889","evidence_type":"候选实验后续","extra":[["作者稿v3及实验判据","https://arxiv.org/abs/2608.15745v3"]],"heading":"Mg₂RhH₆从预测家族进入高压实验","headline":"起始24 K／30 GPa；29 K／53 GPa","id":"13","pressure":"30/53 GPa；卸压条件另记","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1021/jacs.6c08889"},{"label":"作者稿v3及实验判据","url":"https://arxiv.org/abs/2608.15745v3"}],"progress_steps":[{"detail":"跟进Mg₂RhH₆候选","kind":"synthesis","label":"高压合成","status":"completed"},{"detail":"30/53 GPa下起始24/29 K","kind":"measurement","label":"高压测量","status":"completed"},{"detail":"近常压恢复绝缘；未实现常压预测","kind":"ambient_validation","label":"常压超导","status":"not_reported"}],"publication":"Journal of the American Chemical Society 148, 36854–36862 (2026)","reference_point":"按结构、压力和Tc判据追踪预测的实验后续；同化学式不代表验证了同一预测条件。","result":"在先前机器学习辅助筛选所涉及的Mg₂XH₆家族中，实验合成Mg₂RhH₆，约30 GPa报告电阻起始Tc约24 K，约53 GPa最高29 K，并观察到零电阻和磁场抑制转变。","reviewed_on":"2026-11-01","short":"Wu等 Mg₂RhH₆后续","stage":"候选实验后续","tc_criterion":"电阻起始24/29 K","team":"Linjing Wu等，中国多机构实验团队","title":"Superconducting Hydride Mg₂RhH₆ Experimentally Achieved at Lower Pressure","url":"https://doi.org/10.1021/jacs.6c08889","verified_version":"已核作者稿；后续实验非新AI闭环","year":"2026"},{"boundary":"这是已发表的理论复核，不是实验否定，也不是在完全相同结构下把140 K简单修正为22 K；变化的结构状态和物理近似必须一起记录。","category":"计算预测","doi":"10.1103/w7rx-sknt","evidence_type":"理论复核","extra":[["作者稿v3","https://arxiv.org/abs/2604.12367v3"]],"heading":"量子与热涨落改变Li₂AuH₆预测","headline":"变化后的结构状态预测约22 K","id":"14","pressure":"常压情景","primary_refs":[{"label":"原始来源","url":"https://journals.aps.org/prb/abstract/10.1103/w7rx-sknt"},{"label":"作者稿v3","url":"https://arxiv.org/abs/2604.12367v3"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Physical Review B 114, 014508，2026年7月16日","reference_point":"谐声子没有虚频不足以保证候选在量子和热涨落下仍保持目标结构。","result":"路径积分分子动力学考察Li₂AuH₆和Li₂AgH₆的动力学稳定性。前者保留Li–Au骨架，但氢部分二聚化并扩散；在这一结构状态下，随机路径积分方法估计Tc约22 K。","reviewed_on":"2026-11-01","short":"Ding等 Li₂AuH₆复核","stage":"理论复核","tc_criterion":"变化后结构状态的计算Tc","team":"Yucheng Ding、Haoran Chen、Junren Shi，北京大学","title":"Kinetic instability and superconductivity in Li₂AuH₆ and Li₂AgH₆ at ambient pressure","url":"https://journals.aps.org/prb/abstract/10.1103/w7rx-sknt","verified_version":"Phys. Rev. B 114, 014508 (2026)","year":"2026"},{"boundary":"已核出版社摘要，未取得订阅全文；具体压力数值不作推断。镍氧化物电子结构与La₃Ni₂O₇相似是计算线索，没有相应合成或超导实测证据，也不是共同机制的证明。","category":"计算预测","doi":"10.1103/wn98-9yc7","evidence_type":"模型预测与电子结构计算","heading":"机器学习筛选镍氧化物与硼碳氮材料","headline":"高压镍氧化物预测61.6／70.3 K","id":"15","pressure":"高压；具体数值未核","primary_refs":[{"label":"原始来源","url":"https://journals.aps.org/prb/abstract/10.1103/wn98-9yc7"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Physical Review B 113, 054521 (2026)","reference_point":"候选可来自不同材料家族，但应区分由模型预测的Tc、电子结构相似性与直接配对计算。","result":"机器学习结合第一性原理计算，筛选B–C–N化合物和双层镍氧化物。两种B₂CN结构预测Tc为47.6、43.7 K；高压Tb₃Ni₂O₇、Ac₃Ni₂O₇的机器学习预测分别为61.6、70.3 K。","reviewed_on":"2026-11-01","short":"Li等 镍氧化物与B C N","stage":"理论预测","tc_criterion":"计算/模型Tc","team":"Xiaoying Li等，中科院合肥物质科学研究院等","title":"Machine learning accelerated search for superconductors in B-C-N based compounds and R3Ni2O7-type nickelates","url":"https://journals.aps.org/prb/abstract/10.1103/wn98-9yc7","verified_version":"出版社摘要；全文方法未核","year":"2026"},{"boundary":"属于理论预测。50 GPa虽然低于许多超氢化物的研究压力，仍然是高压；该文没有报告RbH₁₂超导的实验实现。","category":"计算预测","doi":"10.1103/PhysRevB.101.144505","evidence_type":"理论计算","heading":"把降低压力纳入氢化物搜索目标","headline":"RbH₁₂在50 GPa预测最高115 K","id":"16","inspection":"Publisher citation and abstract inspected; no subscription barrier bypassed.","pressure":"50 GPa","primary_refs":[{"label":"原始来源","url":"https://journals.aps.org/prb/abstract/10.1103/PhysRevB.101.144505"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Physical Review B 101, 144505 (2020)","reference_point":"候选排序可以同时考虑温度和所需压力；明确多目标取舍，而不只按预测Tc排序。","result":"机器学习先判断值得搜索的氢化物体系，再开展晶体结构搜索、金属性与稳定性筛选及电子—声子计算。RbH₁₂在50 GPa的计算Tc最高约115 K。","reviewed_on":"2026-11-01","short":"Hutcheon等 RbH₁₂","stage":"理论预测","tc_criterion":"计算Tc最高115 K","team":"Michael J. Hutcheon、Alice M. Shipley、Richard J. Needs，剑桥大学","title":"Predicting novel superconducting hydrides using machine learning approaches","url":"https://journals.aps.org/prb/abstract/10.1103/PhysRevB.101.144505","verified_version":"正式论文及作者计算结果","year":"2020"},{"boundary":"候选由另一个模型评分，没有相应合成与超导测量。化学配方和模型间一致性均不能证明晶体能形成或具有指定Tc。","category":"计算预测","doi":"10.1021/acsami.3c00593","evidence_type":"生成配方与模型评分","extra":[["PubMed题录与摘要","https://pubmed.ncbi.nlm.nih.gov/37322591/"]],"heading":"CVAEGAN按目标温度生成配方","headline":"数百个预测Tc\u003e77 K的候选","id":"17","inspection":"Publisher and PubMed abstract inspected. Formula and129.4K match abstract.","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1021/acsami.3c00593"},{"label":"PubMed题录与摘要","url":"https://pubmed.ncbi.nlm.nih.gov/37322591/"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"ACS Applied Materials \u0026 Interfaces 15, 30029–30038 (2023)","reference_point":"把目标性质作为生成条件；后续验证需使用独立证据，避免生成模型与评分模型相互确认。","result":"结合条件变分自编码器与生成对抗网络，在给定Tc条件下生成化学配方，再用已有Tc模型评估。作者提出数百个预测Tc超过77 K的候选；Hg₀.₃₇Ba₁.₇₃Ca₁.₁₈Cu₂.₄₁O₆.₉₃Tl₀.₆₉配方的预测值为129.4 K。","reviewed_on":"2026-11-01","short":"Zhong等 CVAEGAN","stage":"成分生成","tc_criterion":"另一模型评分Tc","team":"Chengquan Zhong等，哈尔滨工业大学","title":"Deep Generative Model for Inverse Design of High-Temperature Superconductor Compositions with Predicted Tc \u003e 77 K","url":"https://doi.org/10.1021/acsami.3c00593","verified_version":"正式论文；无候选实验","year":"2023"},{"boundary":"与条目06的SuperDiff是两项不同工作。200个候选未经实验确认；电中性、掺杂有效性和态密度检查不等于超导证据，也没有解决合成可行性。","category":"计算预测","doi":"10.1002/inf2.12519","evidence_type":"掺杂配方生成","extra":[["作者代码目录","https://github.com/852569069/Supercon_Diffusion"]],"heading":"Supercon Diffusion显式生成掺杂比例","headline":"提出200个潜在高Tc候选","id":"18","inspection":"Publisher full text inspected: abstract, methods, results, conclusion, data availability.","pressure":"未核具体压力","primary_refs":[{"label":"原始来源","url":"https://onlinelibrary.wiley.com/doi/full/10.1002/inf2.12519"},{"label":"作者代码目录","url":"https://github.com/852569069/Supercon_Diffusion"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"InfoMat 6, e12519 (2024)","reference_point":"掺杂比例值得单独建模，但生成结果仍需结构、稳定性、独立物理计算与样品实验逐级核验。","result":"用三通道矩阵表示元素及精细计量，以目标Tc为条件训练扩散模型，生成掺杂配方。论文列出200个潜在高Tc候选，并对部分候选进行电子态密度分析。","reviewed_on":"2026-11-01","short":"Zhong等 Supercon Diffusion","stage":"成分生成","tc_criterion":"模型Tc；非实测","team":"Chengquan Zhong等，哈尔滨工业大学等","title":"High-performance diffusion model for inverse design of high Tc superconductors with effective doping and accurate stoichiometry","url":"https://onlinelibrary.wiley.com/doi/full/10.1002/inf2.12519","verified_version":"正式论文；与06为不同工作","year":"2024"},{"boundary":"900多项包含同一成分在不同压力下的重复计算，不是900多种独立材料。无新超导体实验验证；随机划分误差不代表跨家族能力，文中12与8 K误差来自不同测试集，不能当作配对改善。","category":"数据与工具","doi":"10.1088/2752-5724/ad4a94","evidence_type":"计算数据库与模型预测","extra":[["NIST原始摘要","https://www.nist.gov/publications/data-driven-design-high-pressure-hydride-superconductors-using-dft-and-deep-learning"],["作者计算数据","https://doi.org/10.6084/m9.figshare.25270012"]],"heading":"高压氢化物计算数据训练图神经网络","headline":"122个稳定计算条目Tc\u003e39 K","id":"19","pressure":"0–500 GPa；结构/压力组合","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1088/2752-5724/ad4a94"},{"label":"NIST原始摘要","url":"https://www.nist.gov/publications/data-driven-design-high-pressure-hydride-superconductors-using-dft-and-deep-learning"},{"label":"作者计算数据","url":"https://doi.org/10.6084/m9.figshare.25270012"}],"progress_steps":[{"detail":"900多项结构/压力计算","kind":"data","label":"计算数据库","status":"completed"},{"detail":"计算标签的预测误差","kind":"validation","label":"模型验证","status":"completed"},{"detail":"无该文的新超导体实验","kind":"measurement","label":"候选实验","status":"not_reported"}],"publication":"Materials Futures 3, 025602 (2024)","reference_point":"可借鉴压力条件化的结构模型与计算反馈；计算Tc和实验Tc应分开建库和评价。","result":"在0–500 GPa完成900多项结构与压力组合的DFPT计算，其中122项动力学稳定且计算Tc\u003e39 K。ALIGNN由压力下的结构预测计算Tc，机器学习势辅助结构优化。","reviewed_on":"2026-11-01","short":"Wines Choudhary NIST","stage":"计算数据库与预测","tc_criterion":"DFPT/公式Tc","team":"Daniel Wines、Kamal Choudhary，美国NIST","title":"Data-driven design of high pressure hydride superconductors using DFT and deep learning","url":"https://doi.org/10.1088/2752-5724/ad4a94","verified_version":"2024正式论文；非独立材料计数","year":"2024"},{"boundary":"计算结果尚非实验发现。原型AcBeH₆高出凸包131 meV/atom；没有虚频只说明所检验条件下的动力学稳定性，不能证明热力学稳定、可合成或卸压可保留。","category":"计算预测","doi":"10.1016/j.mtphys.2026.102142","evidence_type":"理论计算","heading":"CHGNet辅助较低压力氢化物设计","headline":"CaAuH₆预测70 K／30 GPa；44 K／常压","id":"20","inspection":"Publisher abstract/search-index content inspected; full text not accessed; no bypass.","pressure":"30 GPa及常压","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1016/j.mtphys.2026.102142"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Materials Today Physics 66, 102142 (2026)","reference_point":"通用势模型可加速原型搜索和元素替换，但需把凸包距离、动力学稳定和实验可达性分别记录。","result":"用CHGNet在30 GPa筛查超过100万个M–BeHₙ构型，以亚稳AcBeH₆结构为原型再做元素替换。得到32个在30 GPa动力学稳定的候选，15个在常压仍动力学稳定；CaAuH₆预测Tc为70 K／30 GPa、44 K／常压。","reviewed_on":"2026-11-01","short":"Du等 CaAuH₆","stage":"理论预测","tc_criterion":"计算Tc 70/44 K","team":"Yu Du、Yu Xin等，吉林大学相关团队","title":"High-temperature superconductivity at pressures below 30 GPa via hydrogen-unit metal embedding","url":"https://doi.org/10.1016/j.mtphys.2026.102142","verified_version":"正式论文；动力学稳定非可合成证明","year":"2026"},{"boundary":"这些是计算候选，没有该文的实验验证。0 K的DFT稳定性不能保证有限温度下可合成；17 K只指最高候选的精细估计，不能替代所有候选的初筛结果。","category":"计算预测","doi":"10.1038/s42005-026-02552-4","evidence_type":"计算筛选与精细复核","extra":[["公开全文","https://pmc.ncbi.nlm.nih.gov/articles/PMC12992110/"]],"heading":"从GNoME筛选常压氢化物","headline":"25个AD Tc≥4.2 K；最高精算17 K","id":"21","pressure":"常压计算","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1038/s42005-026-02552-4"},{"label":"公开全文","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12992110/"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Communications Physics 9, 94 (2026)","reference_point":"保存快速筛选与高精度复核之间的修正，观察模型在哪些物理近似下高估或低估。","result":"从490个立方金属氢化物出发，经DFT筛出261个非磁金属候选，再用ALIGNN安排DFPT计算。25个常压候选的Allen–Dynes估计Tc≥4.2 K；最高者LiZrH₆Ru从初筛23.5 K经更精细多带及库仑相互作用计算降至17 K。","reviewed_on":"2026-11-01","short":"Sanna等 GNoME氢化物","stage":"理论预测","tc_criterion":"Allen–Dynes初筛；精算17 K","team":"Antonio Sanna、Tiago F. T. Cerqueira等","title":"Search for thermodynamically stable ambient-pressure superconducting hydrides in the GNoME database","url":"https://doi.org/10.1038/s42005-026-02552-4","verified_version":"2026正式论文","year":"2026"},{"boundary":"正文一处写78204条，主要结果及摘要写78203条；记录数不等于独立样品。80∶20划分不是去掉家族验证，尚需审计重复成分和来源泄漏。候选未经实验确认，数据库和代码的复用许可仍需另核。","category":"数据与工具","doi":"10.1016/j.jmmm.2026.174189","evidence_type":"文献提取与模型候选","extra":[["作者稿v1","https://arxiv.org/html/2512.10847v1"],["数据库入口","https://nemad.org/"]],"heading":"大语言模型从文献提取超导记录","headline":"约7.8万记录；19058种成分","id":"22","pressure":"来源包含压力；须逐条核","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1016/j.jmmm.2026.174189"},{"label":"作者稿v1","url":"https://arxiv.org/html/2512.10847v1"},{"label":"数据库入口","url":"https://nemad.org/"}],"progress_steps":[{"detail":"组成、Tc、压力等记录","kind":"data","label":"文献提取","status":"completed"},{"detail":"71个待验证候选","kind":"design","label":"候选提出","status":"completed"},{"detail":"未报告候选实验确认","kind":"measurement","label":"候选实验","status":"not_reported"}],"publication":"Journal of Magnetism and Magnetic Materials 652, 174189 (2026)","reference_point":"可作为找原文和样品线索的索引；实验与理论来源、测量条件和Tc判据必须逐条保留，不能直接把提取记录当真值。","result":"从论文和手册提取组成、Tc、压力及结构等信息，报告78203条记录、19058种成分；再微调语言模型做分类、Tc回归和逆向设计，并从GNoME提出71个待验证候选。","reviewed_on":"2026-11-01","short":"Itani等 UNH文献建库","stage":"文献建库与预测","tc_criterion":"提取Tc/模型预测；非新增实测","team":"Suman Itani、Yibo Zhang、Ranjit Itani、Jiadong Zang，新罕布什尔大学","title":"Large language models for superconductor discovery","url":"https://doi.org/10.1016/j.jmmm.2026.174189","verified_version":"正式题录与作者稿v1","year":"2026"},{"boundary":"公告表达支持承诺与拟开展方向，没有报告新的超导材料、实测Tc或已实现的发现效率；不能计入实验发现成果。","category":"研究计划","doi":null,"evidence_type":"机构计划公告","heading":"OpenAI公布高温超导科研支持方向","headline":"拟结合AI 仿真 专家与实验","id":"23","inspection":"Official announcement text inspected, Supporting the Genesis Mission section.","pressure":"未报告","primary_refs":[{"label":"原始来源","url":"https://openai.com/index/advancing-the-next-era-of-national-science/"}],"progress_steps":[{"detail":"官方支持承诺已公布","kind":"announcement","label":"计划公告","status":"completed"},{"detail":"AI、仿真、专家与实验协作","kind":"programme","label":"拟开展研究","status":"current"},{"detail":"未报告新的实测超导材料","kind":"measurement","label":"材料成果","status":"not_reported"}],"publication":"官方公告，2026年7月22日","reference_point":"持续跟踪后续具体项目、开放数据和实验论文，以实际结果评价计划的科学产出。","result":"在支持美国能源部Genesis Mission的公告中，将高温超导列为拟开展的大型科研行动方向，计划结合前沿AI、仿真、材料专家与实验，寻找温度更高且压力更实际的超导材料。","reviewed_on":"2026-11-01","short":"OpenAI Genesis支持","source_label":"官方公告","stage":"研究计划公告","tc_criterion":"未报告新的实测Tc","team":"OpenAI及拟参与的科研机构","title":"Advancing the next era of national science","url":"https://openai.com/index/advancing-the-next-era-of-national-science/","verified_version":"官方公告；非研究结果论文","year":"2026"},{"boundary":"公告没有报告具体新超导体。这里的量子力学模拟不等于在量子计算机上计算；后续阶段资助也是竞争性安排，不能当作已获全部经费。","category":"研究计划","doi":null,"evidence_type":"获资助研究计划","heading":"杜兰大学建设物理计算与实验反馈流程","headline":"一期概念验证；尚非材料发现报告","id":"24","inspection":"Official university announcement inspected. Quantum-mechanical simulations, not a quantum-computing hardware claim.","pressure":"未报告","primary_refs":[{"label":"原始来源","url":"https://news.tulane.edu/pr/department-energys-genesis-mission-selects-tulane-team-using-ai-discover-next-generation"}],"progress_steps":[{"detail":"一期概念验证获支持","kind":"announcement","label":"项目公告","status":"completed"},{"detail":"量子力学模拟与AI探索","kind":"programme","label":"拟开展研究","status":"current"},{"detail":"未报告具体新超导体","kind":"measurement","label":"材料成果","status":"not_reported"}],"publication":"杜兰大学官方公告，2026年7月22日","reference_point":"反馈目标应来自独立计算或真实测量；同时记录推荐、执行、失败及下一步选择，便于评估闭环效率。","result":"团队获得Genesis Mission第一阶段概念验证资助，拟在约九个月内建立结合AI、高精度量子力学模拟与实验的流程，让模型学习计算和测量结果，并选择下一步计算或实验。","reviewed_on":"2026-11-01","short":"Tulane Genesis一期项目","source_label":"大学官方公告","stage":"获资助研究计划","tc_criterion":"未报告新的实测Tc","team":"Jianwei Sun主持，杜兰大学及橡树岭国家实验室合作者","title":"Department of Energy's Genesis Mission selects Tulane team using AI to discover next-generation superconductors","url":"https://news.tulane.edu/pr/department-energys-genesis-mission-selects-tulane-team-using-ai-discover-next-generation","verified_version":"官方项目公告；非材料发现","year":"2026"},{"boundary":"精确数值核自作者v3，未逐表对照最终出版版。三者计算声子稳定；前者在凸包上，后两者分别高于凸包51、43 meV/atom。Tc来自后续电子—声子及公式计算，反馈并非实验Tc，也没有这三种候选的实验验证。","category":"计算预测","doi":"10.1038/s41524-026-01971-9","evidence_type":"原子势计算反馈与理论预测","extra":[["数值来源 作者稿v3","https://arxiv.org/html/2505.08159v3"]],"heading":"自更新原子势加速复杂氢化物搜索","headline":"300 GPa预测137／175／200 K","id":"25","pressure":"300 GPa","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-026-01971-9"},{"label":"数值来源 作者稿v3","url":"https://arxiv.org/html/2505.08159v3"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"npj Computational Materials 12, 101 (2026)","reference_point":"高保真计算可用于纠正势模型并选择下一批结构，但势的精度、结构可合成性和实测超导性能仍需分别验证。","result":"ACNN在结构搜索中用DFT能量、力和应力反馈更新。作者v3报告搜索5964338个Mg–Ca–H构型；300 GPa下，MgCa₃H₂₃、Mg₂CaH₁₈、MgCa₂H₂₁的计算Tc分别为137、175、200 K。","reviewed_on":"2026-11-01","short":"Li等 ACNN结构搜索","stage":"理论预测","tc_criterion":"电子—声子计算Tc","team":"Jiaxiang Li、Junwei Feng等，吉林大学及合作机构","title":"Self-optimizing machine learning potential assisted automated workflow for highly efficient complex systems material design","url":"https://www.nature.com/articles/s41524-026-01971-9","verified_version":"精确数值核自作者v3；未逐表核最终版","year":"2026"},{"boundary":"所有所获超导候选均高于计算凸包；SrBe₄H₁₂高出333 meV/atom。非平衡制备、淬火或薄膜路线只是可能途径，尚未证实可制得目标样品。题录、摘要及机构存档表格片段可核，完整方法未全部获取。","category":"计算预测","doi":"10.1016/j.commt.2026.100052","evidence_type":"理论计算","extra":[["作者机构题录","https://research.aalto.fi/en/publications/machine-learning-driven-exploration-of-hydride-superconductors-at/"]],"heading":"大规模探索常压亚稳氢化物","headline":"600多个计算Tc\u003e20 K的候选","id":"26","pressure":"常压计算","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1016/j.commt.2026.100052"},{"label":"作者机构题录","url":"https://research.aalto.fi/en/publications/machine-learning-driven-exploration-of-hydride-superconductors-at/"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Computational Materials Today 10, 100052 (2026)","reference_point":"常压目标不应掩盖较大的热力学不稳定性；候选排序应同时保留稳定性与预测温度。","result":"机器学习从超过200万结构中安排约5900个候选做DFT和DFPT，得到600多个计算Tc\u003e20 K的常压氢化物。SrBe₄H₁₂又写作Sr(BeH₃)₄，计算Tc为76.7 K，是其中一个代表而非全表最高值。","reviewed_on":"2026-11-01","short":"Pires Marques等 常压搜索","stage":"理论预测","tc_criterion":"DFT/DFPT计算Tc","team":"Paulo R. Pires、Miguel A. L. Marques等","title":"Machine learning driven exploration of hydride superconductors at ambient pressure","url":"https://doi.org/10.1016/j.commt.2026.100052","verified_version":"题录/摘要/机构表格片段；方法未全核","year":"2026"},{"boundary":"高Tc测试的81.26%仅为651条已知高Tc记录中预测也\u003e88 K的比例，MAE为10.15 K。补充材料另有1387条铁基留出，CNN MAE12.1 K；它验证已知超导体回归，不是Pu候选命中。负标签含未报Tc赋0 K；作者做了删除未知项等敏感性检验，但这些仍非逐样品实测阴性。","category":"计算预测","doi":"10.1038/s41598-026-76977-w","evidence_type":"模型外推候选","heading":"钚基与含氢候选的模型外推研究","headline":"Pu₂Co₁₇的CNN预测88.6 K","id":"27","pressure":"候选压力未核","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41598-026-76977-w"}],"progress_steps":[{"detail":"模型或结构搜索提出候选","kind":"design","label":"候选设计","status":"completed"},{"detail":"预测指标与物理近似见证据边界","kind":"calculation","label":"计算评估","status":"completed"},{"detail":"该条未报告相应候选超导实验","kind":"measurement","label":"实验验证","status":"not_reported"}],"publication":"Scientific Reports，2026年10月29日早期接收稿","reference_point":"分别记录阈值召回、Tc误差、家族留出和候选实验验证；模型超出训练数值范围不等于发现可靠的新材料。","result":"比较传统模型与神经网络，筛选晶体数据库，报告22个预测Tc\u003e50 K的钚基候选及40多个含氢候选。Pu₂Co₁₇的CNN／LSTM预测为88.6／90.0 K，均未实验确认。部分含氢候选的LSTM值超过100 K，不能把摘要约100 K当全模型上限。","reviewed_on":"2026-11-01","short":"Gashmard等 DataG筛选","stage":"模型候选预测","tc_criterion":"CNN/LSTM预测；非实测","team":"H. Gashmard、H. Shakeripour、M. Alaei，伊斯法罕理工大学","title":"Genome-inspired AI for extrapolative discovery of high-temperature superconductors","url":"https://www.nature.com/articles/s41598-026-76977-w","verified_version":"早期接收稿及补充材料","year":"2026"},{"boundary":"并非AI独立生成有序晶体；位点混占尚未完全确定。正文将零电阻写为约6 K，图注写5.4 K，不能将5.4 K冒充统一50%电阻判据。Ge对照在1.8 K以上未见超导；随机划分84%准确率不是实验命中率。","category":"实验研究","doi":"10.1140/epjp/s13360-024-05947-w","evidence_type":"抗磁/零电阻/比热验证","extra":[["作者代码；不等于实验曲线原数组","https://github.com/danielkaplan137/TcMLPred"]],"heading":"化学经验与深度学习辅助发现sigma相超导体","headline":"约5.4 K；抗磁、零电阻与比热支持","id":"28","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://link.springer.com/article/10.1140/epjp/s13360-024-05947-w"},{"label":"作者代码；不等于实验曲线原数组","url":"https://github.com/danielkaplan137/TcMLPred"}],"progress_steps":[{"detail":"模型辅助化学经验","kind":"design","label":"推荐配方","status":"completed"},{"detail":"抗磁、零电阻和比热","kind":"measurement","label":"多判据验证","status":"completed"},{"detail":"混占未全定；Ge对照有限温区阴性","kind":"phase_validation","label":"剩余结构问题","status":"current"}],"publication":"The European Physical Journal Plus 140, 58，2025年1月22日","reference_point":"推荐、实际产物及多种超导判据分别登记；成功与有限温区失败一起反馈。","result":"成分深度网络辅助化学经验筛选sigma相材料。Mo₄Re₂Si投料形成约Mo₂₀Re₆Si₄产物；磁化交点与等熵比热给出Tc约5.4 K，电阻也降至零。模型预测约6 K。","reviewed_on":"2026-11-01","short":"Kaplan等 Mo₂₀Re₆Si₄","stage":"实验验证","tc_criterion":"磁化交点与等熵比热5.4 K","team":"Daniel Kaplan、Adam Zheng、Weiwei Xie等，Rutgers及合作机构","title":"Deep learning-based superconductivity prediction and experimental tests","url":"https://link.springer.com/article/10.1140/epjp/s13360-024-05947-w","verified_version":"2025最终论文；电阻正文/图注差异保留","year":"2025"},{"boundary":"Pd₂NiTe₂约5%屏蔽体积分数，伴随4.5 wt%的含Ni PdTe型杂相，两个百分比不可等同。作者支持本征超导解释，但明确不能排除复杂超导杂相；没有以零电阻和比热联合确认该目标相。PdBiTe此前已有超导记载。","category":"实验研究","doi":"10.1038/s41524-023-01023-6","evidence_type":"抗磁信号；杂相归因未完全排除","extra":[["作者代码","https://github.com/ClaudioPereti/From_individual_elements_to_macroscopic_materials"]],"heading":"DeepSet筛选矿物类似物进入低温实验","headline":"1.06 K抗磁起始；杂相仍待排除","id":"29","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-023-01023-6"},{"label":"作者代码","url":"https://github.com/ClaudioPereti/From_individual_elements_to_macroscopic_materials"}],"progress_steps":[{"detail":"DeepSet选择合成类似物","kind":"design","label":"矿物筛选","status":"completed"},{"detail":"Pd₂NiTe₂样品起始1.06 K","kind":"measurement","label":"抗磁信号","status":"completed"},{"detail":"含Ni PdTe型杂相尚未完全排除","kind":"phase_validation","label":"杂相归因","status":"current"}],"publication":"npj Computational Materials 9, 71，2023年5月2日","reference_point":"样品出现信号与目标物相本征超导须分开；模型推荐后的物相归因也是验证的一部分。","result":"DeepSet按元素属性和配比筛选矿物清单，选择3种材料的合成类似物。Pd₂NiTe₂样品在1.06 K出现交流抗磁起始；PdBiTe在2.10 K出现抗磁，两个Pd₃HgTe₃样品至0.45 K未见超导。","reviewed_on":"2026-11-01","short":"Pereti等 Pd₂NiTe₂","stage":"实验信号，归因有限","tc_criterion":"ZFC交流抗磁起始1.06 K","team":"Claudio Pereti、Kevin Bernot、Duccio Fanelli等，佛罗伦萨及合作机构","title":"From individual elements to macroscopic materials: in search of new superconductors via machine learning","url":"https://www.nature.com/articles/s41524-023-01023-6","verified_version":"2023最终论文；杂相与屏蔽分母分开","year":"2023"},{"boundary":"XRD显示预测晶体一般未形成，实际主要是无序BCC固溶体或多相。Re₄TaZr样品比热显示约一半在5.3 K超导，作者归于Re₂Zr。9/18不是成功合成9种预测新晶体；阴性只指4.2 K以上未见信号。数值以最终出版表1为准，不混用预印本版本。","category":"实验研究","doi":"10.1038/s41524-026-02117-7","evidence_type":"合成样品信号；目标结构一般未形成","extra":[["最终出版全文","https://www.nature.com/articles/s41524-026-02117-7.pdf"],["作者代码（MIT）","https://github.com/paprakash/GuidedMatDiffusion"],["作者数据入口；单独许可待核","https://huggingface.co/datasets/paprakash/GuidedMatDiffusion_data"]],"heading":"引导扩散生成结构后的合成与物相检验","headline":"18种组成中9种出现\u003e4.2 K信号","id":"30","pressure":"未报告外加高压","primary_refs":[{"label":"原始来源","url":"https://www.nature.com/articles/s41524-026-02117-7"},{"label":"最终出版全文","url":"https://www.nature.com/articles/s41524-026-02117-7.pdf"},{"label":"作者代码（MIT）","url":"https://github.com/paprakash/GuidedMatDiffusion"},{"label":"作者数据入口；单独许可待核","url":"https://huggingface.co/datasets/paprakash/GuidedMatDiffusion_data"}],"progress_steps":[{"detail":"20万结构经计算筛选","kind":"design","label":"结构生成","status":"completed"},{"detail":"18种组成中9种\u003e4.2 K信号","kind":"measurement","label":"样品检验","status":"completed"},{"detail":"主要是BCC固溶体或混相","kind":"phase_validation","label":"结构未形成","status":"current"}],"publication":"npj Computational Materials 12, 286，2026年5月28日首次上线","reference_point":"把生成目标、合成组成、实际物相与测得信号分别入库；结构未形成是有价值的失败反馈。","result":"DiffCSP先学晶体结构，再用计算超导标签微调；生成20万结构，去重34027个，筛出773个计算Tc\u003e5 K候选。18种组成进入实验，其中9个样品出现4.2 K以上抗磁信号；最终论文报告抗磁起始Tc为4.8–9.7 K。","reviewed_on":"2026-11-01","short":"Prakash等 Guided diffusion","stage":"实验信号，目标结构未形成","tc_criterion":"交流抗磁起始4.8–9.7 K","team":"Pawan Prakash、Richard G. Hennig等，佛罗里达大学及合作机构","title":"Guided diffusion for the discovery of new superconductors","url":"https://www.nature.com/articles/s41524-026-02117-7","verified_version":"2026最终出版表1；不混用作者v1表格","year":"2026"},{"boundary":"这是特定样品与调控范围内的否定结果，不能转成所有压力和掺杂条件下的母体负标签。氧间隙等补偿缺陷可阻止有效载流子掺杂；数据不能只简化为一个Tc=0。","category":"实验研究","doi":"10.1088/1361-648X/ad42f3","evidence_type":"条件限定的否定实验","extra":[["作者机构公开全文","https://schlom.mse.cornell.edu/sites/default/files/research%20pdfs/Hensling_2024_J._Phys.__Condens._Matter_36_315602.pdf"],["作者数据入口","https://doi.org/10.34863/xg24-bj80"]],"heading":"Ba₃In₂O₆高温候选的实验否定结果","headline":"已测试薄膜与调控条件未见超导","id":"31","pressure":"所测薄膜/调控范围","primary_refs":[{"label":"原始来源","url":"https://doi.org/10.1088/1361-648X/ad42f3"},{"label":"作者机构公开全文","url":"https://schlom.mse.cornell.edu/sites/default/files/research%20pdfs/Hensling_2024_J._Phys.__Condens._Matter_36_315602.pdf"},{"label":"作者数据入口","url":"https://doi.org/10.34863/xg24-bj80"}],"progress_steps":[{"detail":"跟进高Tc材料预测","kind":"design","label":"检验候选","status":"completed"},{"detail":"所测范围均未见超导","kind":"measurement","label":"多种调控实验","status":"completed"},{"detail":"不能等同所有调控下母体无潜力","kind":"boundary","label":"条件边界","status":"current"}],"publication":"Journal of Physics: Condensed Matter 36, 315602，2024年5月9日","reference_point":"反馈应记录候选为何落空、实际相和载流子调控是否成功，并保留未成功的尝试及测量边界。","result":"结构类比和后来的机器学习78 K预测促成对Ba₃In₂O₆的检验。带保护层外延薄膜实测面内、c轴光学带隙为2.99、2.83 eV。研究尝试晶格位掺杂、表面碱金属掺杂、光激发、氢还原及离子液体栅控，在所测范围均未诱导超导。","reviewed_on":"2026-11-01","short":"Hensling等 Ba₃In₂O₆","stage":"条件限定的否定实验","tc_criterion":"所测范围未见超导；非Tc=0","team":"F. V. E. Hensling、D. G. Schlom等，Cornell及合作机构","title":"Is Ba3In2O6 a high-Tc superconductor?","url":"https://doi.org/10.1088/1361-648X/ad42f3","verified_version":"2024正式论文及补充材料","year":"2024"}],"reviewed_on":"2026-11-01","schedule":{"automation_id":"ai","frequency":"daily","note":"已设置每日检索；不代表每日完成全部原文核验。条目核验日期单独记录。","status":"active_schedule","time":"09:00","timezone":"America/Chicago"},"schema_version":1,"source":{"memo_version":"1.1","scope":"29项研究与2项研究计划；摘要与引用，不含论文全文或图像","sha256":"4eb45b8bffc40442695ff9dd0b63d5a5791dcf461c758f613a8810b42bb4d115"},"updated":"2026-11-01"};
